using System;
using System.IO;
using System.Linq;
internal static class DofusVisualAcceptance {
 internal static void Test(string folder){CharacterPortraits.Test(Path.Combine(folder,"main-portraits"));CompanionInstructions.Test(Path.Combine(folder,"main-instructions"));if(DofusVisuals.Icon("rsa-rush-sylvestre-accelere","Rush Sylvestre").PixelWidth!=128||DofusVisuals.Icon("inconnu","Autre parcours")!=null)throw new Exception("Icônes Dofus intégrées");var store=new Store(Path.Combine(folder,"portrait-backup"));var c=new DofusCharacter{id="portrait-backup",name="Test"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;var bytes=CharacterPortraits.Prepare(Path.Combine(folder,"main-portraits/sample.webp"));string hash=CharacterPortraits.Save(store,bytes);store.Value.portraits[c.id]=hash;store.Save();var archive=Path.Combine(folder,"portrait.mespace");FullBackup.Export(store,archive);var target=new Store(Path.Combine(folder,"portrait-restored"));using(var plan=FullBackup.Prepare(target,archive)){if(plan.MissingFiles!=0)throw new Exception("Portrait absent de la sauvegarde");FullBackup.Commit(target,plan);}if(target.Value.portraits[c.id]!=hash||CharacterPortraits.Load(target,hash)==null)throw new Exception("Portrait perdu à la restauration");string json=Path.Combine(folder,"portrait.json");store.Export(json);var imported=new Store(Path.Combine(folder,"portrait-imported"));imported.Import(json);if(imported.Value.portraits[c.id]!=hash)throw new Exception("Association du portrait perdue à l’import JSON");File.WriteAllText(Path.Combine(folder,"DOFUS_VISUAL_PASS.txt"),"PASS: embedded Dofus icons; native WebP preparation; portraits saved per character; full backup and restore with portrait bytes; JSON association import; companion instructions cache and original text preference.");}
 internal static int Run(string folder){try{Directory.CreateDirectory(folder);Test(folder);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"DOFUS_VISUAL_FAIL.txt"),ex.ToString());return 1;}}
}
